uploads = [
    item.get("json", {}) if isinstance(item, dict) else {}
    for item in _items
]

if len(uploads) < 2:
    raise ValueError("Expected two Cloudinary upload items.")


def text_value(item, key):
    value = item.get(key)
    return "" if value is None else str(value).lower()


def is_tex_upload(item):
    public_id = text_value(item, "public_id")
    secure_url = text_value(item, "secure_url")
    url = text_value(item, "url")

    return (
        public_id.endswith(".tex")
        or secure_url.endswith(".tex")
        or url.endswith(".tex")
    )


def is_pdf_upload(item):
    file_format = text_value(item, "format")
    public_id = text_value(item, "public_id")
    secure_url = text_value(item, "secure_url")
    url = text_value(item, "url")

    return (
        file_format == "pdf"
        or public_id.endswith(".pdf")
        or secure_url.endswith(".pdf")
        or url.endswith(".pdf")
    )


tex_upload = next((item for item in uploads if is_tex_upload(item)), None)
pdf_upload = next((item for item in uploads if is_pdf_upload(item)), None)

if tex_upload is None:
    raise ValueError("Could not identify the TEX upload result.")

if pdf_upload is None:
    raise ValueError("Could not identify the PDF upload result.")

tex_url = tex_upload.get("secure_url") or tex_upload.get("url")
pdf_url = pdf_upload.get("secure_url") or pdf_upload.get("url")

if not tex_url or not pdf_url:
    raise ValueError("Cloudinary did not return both TEX and PDF URLs.")

source = _("Normalize Input").first()["json"]

return [
    {
        "json": {
            "document_type": source.get("document_type"),
            "application_id": source.get("application_id"),
            "job_id": source.get("job_id"),
            "company_name": source.get("company_name"),
            "job_title": source.get("job_title"),
            "tex_url": tex_url,
            "pdf_url": pdf_url,
            "tex_public_id": tex_upload.get("public_id"),
            "pdf_public_id": pdf_upload.get("public_id"),
        }
    }
]
